PRAGMA foreign_keys = ON;

UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"graceful clearly adult lunar princess in long layered court robes","appearance":{"face":["clearly adult refined face with distant calm gaze"],"body":["slender graceful adult proportions"]},"costumeLanguage":["historically inspired layered court robes in moon-white, ink-blue and restrained silver"],"paletteCues":["moon white","ink blue","silver"],"temperament":["serene","distant","ethereal"],"mythologicalFacts":["princess of the Bamboo Cutter tale who returns to the moon"],"originalDesignChoices":["Keep moon and bamboo identity elegant and restrained."],"avoid":["generic anime schoolgirl","youth-coded sexualization","specific modern franchise likeness"],"canonicalPrompt":"Depict Kaguya-hime as an original MythCanvas lunar princess. Preserve the full moon, bamboo, layered court robes and quiet distance. Keep her clearly adult, elegant and otherworldly without copying a modern anime design."}') WHERE id='character-kaguya';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"stately adult solar goddess framed by a clean circular sun disk and sacred mirror","appearance":{"face":["clearly adult composed face with warm sovereign gaze"],"body":["graceful adult proportions with upright ceremonial posture"]},"costumeLanguage":["refined Japanese ceremonial layers with white, vermilion and restrained gold"],"paletteCues":["sun white","vermilion","gold"],"temperament":["radiant","sovereign","benevolent"],"mythologicalFacts":["solar kami and central deity of Takamagahara"],"originalDesignChoices":["Use mirror and sun as primary identifiers; sacred light over spectacle."],"avoid":["generic anime miko","overloaded fantasy armor","specific modern franchise likeness"],"canonicalPrompt":"Depict Amaterasu as an original MythCanvas solar kami. Preserve the sun disk, sacred mirror and luminous sovereign presence. Use refined Japanese ceremonial layering with restrained vermilion and gold, keeping the image sacred rather than flashy."}') WHERE id='character-amaterasu';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"powerful adult storm god with wind-tossed garments and a long sword cutting a strong diagonal","appearance":{"face":["rugged adult face with fierce heroic expression"],"body":["strong athletic adult build"]},"costumeLanguage":["ancient Japanese warrior garments with layered robes, cords and practical sword fittings"],"paletteCues":["storm indigo","steel","white foam"],"temperament":["impulsive","fierce","heroic"],"mythologicalFacts":["storm and sea kami famed for defeating Yamata no Orochi"],"originalDesignChoices":["Keep storm movement in cloth and cloud; avoid late samurai armor as canonical form."],"avoid":["generic anime swordsman","oversized samurai armor","specific modern franchise likeness"],"canonicalPrompt":"Depict Susanoo as an original MythCanvas storm deity. Preserve the Totsuka sword, storm clouds and Yamata no Orochi association. Use ancient Japanese warrior garments with dynamic wind movement and a forceful adult heroic presence."}') WHERE id='character-susanoo';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"tall reserved adult lunar deity with a clean crescent-and-night vertical composition","appearance":{"face":["androgynous but clearly adult refined face with cool distant gaze"],"body":["slender adult proportions"]},"costumeLanguage":["restrained ancient Japanese court layers in dark indigo, moon-white and silver"],"paletteCues":["moon silver","night indigo"],"temperament":["reserved","cool","ceremonial"],"mythologicalFacts":["moon kami in Shinto tradition"],"originalDesignChoices":["Lunar identity comes from light and restraint, not sci-fi effects."],"avoid":["generic anime bishonen","cyber moon armor","specific modern franchise likeness"],"canonicalPrompt":"Depict Tsukuyomi as an original MythCanvas moon deity. Preserve the moon disk, night sky and silver lunar light. Use restrained ancient Japanese court layers and a composed adult presence with minimal ornament."}') WHERE id='character-tsukuyomi';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"mature creator god with long spear and broad sea-making gesture","appearance":{"face":["mature adult face with solemn paternal authority"],"body":["tall mature adult build"]},"costumeLanguage":["archaic Japanese ceremonial robes with natural-fiber textures and simple divine regalia"],"paletteCues":["sea blue","stone white"],"temperament":["solemn","creative","purifying"],"mythologicalFacts":["creator kami who with Izanami formed the Japanese islands and later performed purification"],"originalDesignChoices":["Emphasize creation and purification rather than warrior imagery."],"avoid":["generic samurai king","specific modern franchise likeness"],"canonicalPrompt":"Depict Izanagi as an original MythCanvas creator kami. Preserve the Ame-no-Nuboko spear, sea-creation imagery and purification motif. Use archaic Japanese ceremonial robes and a mature, solemn divine presence."}') WHERE id='character-izanagi';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"mature creator goddess whose elegant upper-world silhouette carries restrained Yomi shadow at the edges","appearance":{"face":["mature adult face with solemn beauty and grave underworld undertone"],"body":["graceful mature adult proportions"]},"costumeLanguage":["archaic ceremonial robes transitioning subtly from warm creation colors to Yomi-dark layers"],"paletteCues":["ash crimson","charcoal","ivory"],"temperament":["maternal","solemn","chthonic"],"mythologicalFacts":["creator kami who later becomes associated with Yomi after death"],"originalDesignChoices":["Show creation/death duality without zombie horror or gore."],"avoid":["gore","generic ghost woman","specific modern franchise likeness"],"canonicalPrompt":"Depict Izanami as an original MythCanvas creator and Yomi goddess. Preserve creation imagery, Yomi shadow and the fire-birth tragedy. Use archaic Japanese ceremonial robes with a controlled life-to-underworld transition, never horror gore."}') WHERE id='character-izanami';
