UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"muscular adult thunder deity framed by a circular arc of thunder drums","appearance":{"face":["fierce adult oni-like face with controlled divine intensity"],"body":["powerful muscular adult build"]},"costumeLanguage":["minimal ancient storm-deity garments with sash, cloud forms and drum harness"],"paletteCues":["electric indigo","storm white","red"],"temperament":["fierce","energetic","elemental"],"mythologicalFacts":["thunder deity commonly depicted with drums"],"originalDesignChoices":["Oni-like traits remain divine iconography, not horror-monster anatomy."],"avoid":["generic demon boss","modern superhero lightning suit","specific modern franchise likeness"],"canonicalPrompt":"Depict Raijin as an original MythCanvas thunder deity. Preserve the ring of thunder drums, lightning and storm clouds. Use a powerful adult divine body with ancient Japanese storm-deity garments, keeping the oni-like face iconic rather than monstrous."}') WHERE id='character-raijin';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"lean muscular adult wind deity with enormous wind bag sweeping behind the shoulders","appearance":{"face":["weathered adult oni-like face with sharp energetic expression"],"body":["lean powerful adult build"]},"costumeLanguage":["minimal ancient wind-deity garments with scarf-like cloth pulled by airflow"],"paletteCues":["storm green","cloud white","charcoal"],"temperament":["wild","swift","elemental"],"mythologicalFacts":["wind deity commonly depicted carrying a great wind bag"],"originalDesignChoices":["The wind bag is the key silhouette; avoid generic winged air-god imagery."],"avoid":["angel wings","generic demon boss","specific modern franchise likeness"],"canonicalPrompt":"Depict Fūjin as an original MythCanvas wind deity. Preserve the enormous wind bag, streaming clouds and violent airflow. Use a lean powerful adult divine body with ancient Japanese garments and a wild but controlled elemental presence."}') WHERE id='character-fujin';
